k = input(7, "K Neighbors", 1, 20, 1)
referenceLen = input(20, "Reference Length", 10, 50, 1)
marginThresh = input(0.43, "Margin Threshold", 0.1, 1.0, 0.01)
disagreeThresh = input(0.6, "Disagreement Threshold", 0.1, 1.0, 0.05)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Feature vector from raw OHLC only, normalized by close ───
denom = close + 0.000000001
f1Cur = (close - open) / denom
f2Cur = (high - low) / denom
prevC = close[1]
f3raw = (close - prevC) / denom
f3Cur = f3raw
if bar_index == 0 { f3Cur := 0.0 }

// ─── Persistent reference history ───
varip f1Hist = array(0)
varip f2Hist = array(0)
varip f3Hist = array(0)
varip closeHist = array(0)

array.push(f1Hist, f1Cur)
array.push(f2Hist, f2Cur)
array.push(f3Hist, f3Cur)
array.push(closeHist, close)

// ─── KNN-7 Euclidean vote over last 20 completed bars ───
numBars = array.size(closeHist)
upVotes = 0
downVotes = 0
margin = 0.0
absMargin = 0.0
entropy = 1.0

if numBars >= referenceLen + 2 {
    bestDist = array()
    bestTargets = array()
    ii = 0
    while ii < k {
        array.push(bestDist, 999999.0)
        array.push(bestTargets, 0)
        ii := ii + 1
    }
    searchStart = numBars - 1 - referenceLen - 1
    if searchStart < 0 { searchStart := 0 }
    searchEnd = numBars - 2
    jj = searchStart
    while jj <= searchEnd {
        d1 = f1Cur - f1Hist[jj]
        d2 = f2Cur - f2Hist[jj]
        d3 = f3Cur - f3Hist[jj]
        dist = sqrt(d1 * d1 + d2 * d2 + d3 * d3)
        lbl = 0
        if closeHist[jj + 1] > closeHist[jj] { lbl := 1 }
        insertIdx = -1
        m = 0
        while m < k {
            if dist < bestDist[m] {
                insertIdx := m
                m := k
            }
            m := m + 1
        }
        if insertIdx >= 0 {
            m = k - 1
            while m > insertIdx {
                array.set(bestDist, m, bestDist[m - 1])
                array.set(bestTargets, m, bestTargets[m - 1])
                m := m - 1
            }
            array.set(bestDist, insertIdx, dist)
            array.set(bestTargets, insertIdx, lbl)
        }
        jj := jj + 1
    }
    up = 0
    down = 0
    m = 0
    while m < k {
        if bestDist[m] < 999999.0 {
            if bestTargets[m] == 1 { up := up + 1 }
            else { down := down + 1 }
        }
        m := m + 1
    }
    upVotes := up
    downVotes := down
    tot = upVotes + downVotes
    if tot > 0 {
        margin := (upVotes - downVotes) / tot
        absMargin := abs(margin)
        pUp = upVotes / tot
        pDown = 1.0 - pUp
        termUp = 0.0
        termDown = 0.0
        if pUp > 0.0 { termUp := pUp * log(pUp) }
        if pDown > 0.0 { termDown := pDown * log(pDown) }
        entropy := 0.0 - (termUp + termDown) / log(2.0)
    }
}

// ─── Agreement state: crisp vs contested ───
buyCond = margin >= marginThresh and entropy <= disagreeThresh and bar_index >= referenceLen + 2
sellCond = margin <= 0 - marginThresh and entropy <= disagreeThresh and bar_index >= referenceLen + 2
buySig = buyCond and not buyCond[1]
sellSig = sellCond and not sellCond[1]

// ─── 2D signal markers ───
if buySig { plotshape(bar_index, low, "Buy", "triangleup", "#22cc88") }
if sellSig { plotshape(bar_index, high, "Sell", "triangledown", "#ff4477") }

// ─── 3D signal markers in same pane ───
if buySig { plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 0, "separate") }
if sellSig { plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 0, "separate") }

// ─── 2D channels: independently readable ───
plot(margin, "Vote Margin", "#ffd43b", 2, "separate")
plot(entropy, "Disagreement", "#b48cff", 1, "separate")
hline(0, "#888888", "separate")

// ─── 3D form: height = absMargin, sheath = entropy ───
// Crisp = tall narrow pillar (high margin, low entropy), Contested = short wide flat slab
plot3d(absMargin, "Margin Height", "bars3d", "#22cc88", "separate")
plot3d(entropy, "Disagreement Sheath", "surface", "#b48cff", "separate", 1)

// Multi-Timeframe Siege Signal Analysis Model
// Session range extremes + confirmed 1H structure + quality confidence + hard stop

sessLen = input(20, "Session Length (bars)", 5, 200, 1)
htfLook = input(3, "1H Lookback for Structure (swings)", 2, 20, 1)
confirmBars = input(2, "Structure Confirmation Bars (1H closed)", 1, 10, 1)
confThresh = input(60, "Confidence Threshold for Entry", 0, 100, 1)
stopOff = input(10, "Hard Stop Offset (ticks beyond extreme)", 1, 200, 1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

sessHigh = highest(high, sessLen)
sessLow = lowest(low, sessLen)

htfClose = security("1h", close)
htfHigh = security("1h", high)
htfLow = security("1h", low)

swingHigh = highest(htfHigh, htfLook)
swingLow = lowest(htfLow, htfLook)
swingHighPrev = swingHigh[1]
swingLowPrev = swingLow[1]

bullStruct = htfClose > swingHighPrev and htfLow[1] > htfLow[2]
bearStruct = htfClose < swingLowPrev and htfHigh[1] < htfHigh[2]

bullSiege = crossover(close, sessHigh[1])
bearSiege = crossunder(close, sessLow[1])

bullHtfBreak = htfClose > swingHighPrev and htfClose[1] <= swingHigh[2]
bearHtfBreak = htfClose < swingLowPrev and htfClose[1] >= swingLow[2]

bullConsec = htfClose > swingHighPrev and htfClose[1] > swingHigh[2]
bearConsec = htfClose < swingLowPrev and htfClose[1] < swingLow[2]

var bullCount = 1000000
var bearCount = 1000000
var bullHtfCount = 1000000
var bearHtfCount = 1000000

if bullSiege {
    bullCount := 0
} else {
    bullCount := bullCount[1] + 1
}
if bearSiege {
    bearCount := 0
} else {
    bearCount := bearCount[1] + 1
}
if bullHtfBreak {
    bullHtfCount := 0
} else {
    bullHtfCount := bullHtfCount[1] + 1
}
if bearHtfBreak {
    bearHtfCount := 0
} else {
    bearHtfCount := bearHtfCount[1] + 1
}

bullAligned = bullCount < confirmBars and bullHtfCount < confirmBars
bearAligned = bearCount < confirmBars and bearHtfCount < confirmBars

bullQuality = 50 + (bullConsec ? 25 : 0) + (bullAligned ? 25 : 0)
bearQuality = 50 + (bearConsec ? 25 : 0) + (bearAligned ? 25 : 0)
quality = bullStruct ? bullQuality : bearStruct ? bearQuality : 0
conf = quality / 100

hardStopLong = sessHigh - stopOff
hardStopShort = sessLow + stopOff

buySig = bullSiege and bullStruct and quality >= confThresh
sellSig = bearSiege and bearStruct and quality >= confThresh
exitLongSig = crossunder(close, hardStopLong) or crossunder(close, sessLow[1])
exitShortSig = crossover(close, hardStopShort) or crossover(close, sessHigh[1])

if buySig {
    model.confidence(conf)
    model.stopLoss(stopOff, "abs")
    model.longEntry("siege")
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    model.confidence(conf)
    model.stopLoss(stopOff, "abs")
    model.shortEntry("siege")
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}
if exitLongSig {
    model.longExit("siege")
    plotshape(bar_index, high, "Exit", "x", "#ffcc00")
}
if exitShortSig {
    model.shortExit("siege")
    plotshape(bar_index, low, "Exit", "x", "#ffcc00")
}

plot(sessHigh, "Session High", "#ff4477", 1, "stepline")
plot(sessLow, "Session Low", "#22cc88", 1, "stepline")

// Visible Session Volume Profile Value Signal Analysis Model
// Volume-profile POC + value-area expansion, price leaving value as signal.

profileRows = input(24, "Profile Rows", 10, 48, 1)
vaPct = input(70, "Value Area %", 50, 90, 5)
showVA = input(true, "Show Value Area")
showPOC = input(true, "Show POC")
use3D = input(true, "Use 3D")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Visible session window (rolling visible-session proxy) ───
winLen = 150
if bar_index + 1 < 150 {
    winLen := bar_index + 1
}
if winLen < 10 {
    winLen := bar_index + 1
}
if winLen < 1 {
    winLen := 1
}

hh = highest(high, winLen)
ll = lowest(low, winLen)
rng = hh - ll
if rng <= 0 {
    rng := close * 0.01
}
binH = rng / profileRows
if binH <= 0 {
    binH := close * 0.001
}

// ─── Build per-bin volume sums from hlc3 assignment ───
binVol = array()
i = 0
while i < profileRows {
    array.push(binVol, 0.0)
    i := i + 1
}
totalVol = 0.0
k = 0
while k < winLen {
    tp = (high[k] + low[k] + close[k]) / 3
    vv = volume[k]
    totalVol := totalVol + vv
    bi = floor((tp - ll) / binH)
    if bi < 0 {
        bi := 0
    }
    if bi > profileRows - 1 {
        bi := profileRows - 1
    }
    array.set(binVol, bi, array.get(binVol, bi) + vv)
    k := k + 1
}
if totalVol <= 0 {
    totalVol := 1.0
}

// ─── POC: bin with max volume ───
pocBin = 0
pocVal = array.get(binVol, 0)
i = 1
while i < profileRows {
    v = array.get(binVol, i)
    if v > pocVal {
        pocVal := v
        pocBin := i
    }
    i := i + 1
}
pocPrice = ll + (pocBin + 0.5) * binH
pocStrength = pocVal / totalVol

// ─── Value area: expand from POC adding higher-volume neighbor ───
vaLow = pocBin
vaHigh = pocBin
accum = pocVal
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < profileRows {
    leftVal = 0 - 1.0
    if vaLow > 0 {
        leftVal := array.get(binVol, vaLow - 1)
    }
    rightVal = 0 - 1.0
    if vaHigh < profileRows - 1 {
        rightVal := array.get(binVol, vaHigh + 1)
    }
    if rightVal >= leftVal and vaHigh < profileRows - 1 {
        vaHigh := vaHigh + 1
        accum := accum + rightVal
    } else {
        if vaLow > 0 {
            vaLow := vaLow - 1
            accum := accum + leftVal
        }
    }
    guard := guard + 1
}
vahPrice = ll + (vaHigh + 1) * binH
valPrice = ll + vaLow * binH
vaMid = (vahPrice + valPrice) / 2
insideVA = close >= valPrice and close <= vahPrice
wasInside = insideVA[1]
if bar_index == 0 {
    wasInside := true
}

// ─── Terrain value: price-denominated extrusion where value sits ───
terrainVal = pocPrice + (pocStrength - 0.5) * rng * 0.5 + (vaMid - pocPrice) * 0.15

// ─── Signals: price leaving value (edge-fired events only) ───
buySig = wasInside and close > vahPrice and close[1] <= vahPrice
sellSig = wasInside and close < valPrice and close[1] >= valPrice
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}
if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 1, "3d")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 1, "3d")
}

// ─── POC rail label on new POC bin only (rare, readable) ───
var lastPocBin = -1
if pocBin != lastPocBin and bar_index > winLen {
    label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.0, 1, "3d")
}
lastPocBin := pocBin

// ─── 2D: same information when 3D is off ───
plot(close, "Price", "#ffffff", 1)
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
box.new(bar_index - winLen + 1, vahPrice, bar_index, valPrice, "#22cc8855", "rgba(34,204,136,0.08)", 1, "VAZONE")
text.new(bar_index, pocPrice, "POC", "#ffd43b", 1, "POCTXT")
text.new(bar_index, vahPrice, "VAH", "#22cc88", 1, "VAHTXT")
text.new(bar_index, valPrice, "VAL", "#ff4477", 1, "VALTXT")
if not insideVA {
    bgcolor("rgba(255,136,0,0.05)")
}

// ─── 3D: value terrain + POC labelled rail + VAH/VAL slab ───
plot3d(terrainVal, "Value Terrain", "surface", "#22cc88", "3d", 0)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 1)
plot3d(vahPrice, "VAH", "line3d", "#22cc88", "3d", 2)

// FIX 1: var lvl = highest(high, 20) froze at bar 0 -> plain assignment recomputes every bar.
lvl = highest(high, 20)
// FIX 2: close[-1] peeks at future bar -> close preserves intended breakout logic with no lookahead.
buySig = close > lvl
r = rsi(close, 14)
if buySig {
    // FIX 3: plotshape(true, low, "Buy", shape.triangleup, color.green) is Pine signature -> OakScript positional (bar_index, price, title, style, color).
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if crossover(r, 30) {
    plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
}
// FIX 4: oscillator in pane="3d" renders spiky forest over candles -> pane="separate" per PANE LAW.
plot(r, "RSI", "#b48cff", 1, "line")
plot3d(r, "RSI", "surface", "#b48cff", "separate")
